select
PROD_ASSET_ID prodAssetId,
PROD_ID prodId,
EFF_DATE effDate,
EFF_END_DATE effEndDate
from DIS_PROD_ASSET


		AND	PROD_ID=#{prodId,jdbcType=VARCHAR}


		AND	DATA_STATUS=#{status,jdbcType=VARCHAR}


		AND	PROD_ASSET_ID=#{prodAssetId,jdbcType=VARCHAR}


		AND	PROD_ASSET_ID!=#{excludeId,jdbcType=VARCHAR}
